local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.demonhunter.devourer.Name"] = "Боевой помощник Blizzard"
L["rm.retail.demonhunter.devourer.Description"] = "Рекомендуется для специализации «Пожиратель». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете заклинание или поддерживаете Луч Бездны, ротация ждёт. Рядом с ним — напоминания о том, что помощник оставляет вам: Метаморфоза Бездны, Охота и Клинок Бездны по готовности в бою, Прерывание против прерываемого заклинания и Затуманивание по готовности в бою. В бою заклинания противников скрыты, поэтому Прерывание загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Затуманивания — на ваше усмотрение."
L["rm.retail.demonhunter.devourer.guide.Name"] = "Для справки (Icy Veins)"
L["rm.retail.demonhunter.devourer.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет Разрушителя по Icy Veins. Большинство ваших положительных эффектов скрыты в бою в Midnight, поэтому ротация не может там работать; ярость на Retail скрыта, поэтому Луч Бездны ждёт только своей стоимости. Вне Метаморфозы Бездны: Поглощение при Взрывной душе, Жатва, Жар души, когда он не горит, Клинок Бездны и Охота, как только Метаморфоза Бездны готова, Метаморфоза Бездны, Голодный взмах, Луч Бездны, Поглощение. В ней: Пожирание при Взрывной душе, Луч Бездны, удары Зараженных Бездной, если они у вас есть, Коллапсирующая звезда, Истребление, Пожирание, Жар души. Rotation Master не может считать Фрагменты души, поэтому Жатва и Истребление применяются по готовности. Напоминания: Прерывание и Затуманивание."
L["rm.retail.demonhunter.devourer.simc.Name"] = "Для справки (SimulationCraft)"
L["rm.retail.demonhunter.devourer.simc.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для Разрушителя, который входит в Метаморфозу Бездны, как только она готова. Скрытые боевые данные не дают этой ротации работать в бою в Midnight. Вне её: Клинок Бездны с Укусом пожирателя против не более чем трёх врагов и при полностью накопленной Метаморфозе Бездны, Метаморфоза Бездны, Поглощение при Взрывной душе, Жатва, Луч Бездны, Жар души против групп врагов, Поглощение. В ней: Пожирание при Взрывной душе против одной цели, Охота и Клинок Бездны с Укусом пожирателя, Луч Бездны против групп врагов, Коллапсирующая звезда, Истребление, Луч Бездны, Жар души, Пожирание. Напоминания: Прерывание и Затуманивание."
L["rm.retail.demonhunter.havoc.Name"] = "Боевой помощник Blizzard"
L["rm.retail.demonhunter.havoc.Description"] = "Рекомендуется для специализации «Истребление». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что помощник игры оставляет вам: Метаморфоза и Охота в бою, Коварное отступление, если у вас есть Инерция или Эксергия, Прерывание против прерываемого заклинания, а также Затуманивание, как только оно готово в бою. В бою заклинания противников скрыты, поэтому Прерывание загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Затуманивания — на ваше усмотрение. За вами остаются: перемещение, Мрак и аксессуары."
L["rm.retail.demonhunter.havoc.guide.Name"] = "Для справки (Icy Veins, SimulationCraft и Wowhead)"
L["rm.retail.demonhunter.havoc.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Истребления» по руководствам. Ваши срабатывания, Метаморфоза и Разрыв сущности скрыты от аддонов в бою в Midnight, поэтому этот список не может там работать; читайте его или продублируйте, чтобы поэкспериментировать. Ярость на Retail скрыта, поэтому Клинок Скверны не ждёт свободного места. Альдрахийский разоритель: Клинок разорителя, когда не действуют ни Разрывающий удар, ни Шквал глеф, Удар Хаоса при Разрывающем ударе. Истерзанный Скверной: Разрыв сущности, Танец клинков и Удар Хаоса в Метаморфозе. Затем Танец клинков и Удар Хаоса во время Разрыва сущности, Обжигающий жар при двух зарядах, Пронзающий взгляд, Клинок Скверны ради Инерции, Разрыв сущности, когда до Пронзающего взгляда больше 4 секунд, Танец клинков, Обжигающий жар против двух врагов, Удар Хаоса, Клинок Скверны, Обжигающий жар, Бросок боевого клинка, Рывок Скверны. Напоминания: Метаморфоза, когда Пронзающий взгляд и Танец клинков потрачены, Охота, Коварное отступление, а также Прерывание и Затуманивание."
L["rm.retail.demonhunter.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.demonhunter.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию охотника на демонов). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций охотника на демонов, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.demonhunter.vengeance.Name"] = "Боевой помощник Blizzard"
L["rm.retail.demonhunter.vengeance.Description"] = "Рекомендуется для специализации «Месть». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что помощник оставляет вам: Демонические шипы, Огненное клеймо, Опустошение Скверной и Метаморфоза по готовности в бою, Прерывание против прерываемого заклинания и Затуманивание по готовности в бою. В бою заклинания противников скрыты, поэтому Прерывание загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Затуманивания — на ваше усмотрение. За вами остаются: Инфернальный удар, Мрак, провокации и аксессуары."
L["rm.retail.demonhunter.vengeance.guide.Name"] = "Для справки (Wowhead и Icy Veins)"
L["rm.retail.demonhunter.vengeance.guide.Description"] = "Только для справки, по умолчанию выключена: порядок «Мести» по Wowhead с целями для героических талантов от Icy Veins. Ваши положительные эффекты скрыты в бою в Midnight, поэтому ротация не может там работать; ярость на Retail скрыта, поэтому расходующие приёмы ждут только своей стоимости, а накапливающие не избегают переполнения. Альдрахийский разоритель: Клинок разорителя, Разлом при Разрывающем ударе, Раскалывание душ при Шквале глеф. Затем Разлом при полных зарядах, Взрывная душа против трёх и более врагов, Обжигающий жар, Печать огня, Раскалывание душ против одной цели, Опустошение Скверной, Раскалывание душ, Разлом, Клинок Скверны, Бросок боевого клинка. Rotation Master не может считать Фрагменты души, поэтому Взрывная душа зависит от числа врагов. Напоминания: Демонические шипы, когда они не действуют, Метаморфоза, Огненное клеймо, Печать злобы, Разрубатель душ (Инфернальный удар при двух зарядах выключен), а также Прерывание и Затуманивание."
L["rm.retail.demonhunter.vengeance.simc.Name"] = "Для справки (SimulationCraft)"
L["rm.retail.demonhunter.vengeance.simc.Description"] = "Только для справки, по умолчанию выключена: списки SimulationCraft для «Мести». Скрытые боевые данные не дают этой ротации работать в бою в Midnight, а ярость на Retail скрыта, поэтому пороги ярости опущены. Альдрахийский разоритель: сначала Печать огня и Обжигающий жар, Метаморфоза, цикл Клинка разорителя с Клинком Скверны, Огненное клеймо, Печать злобы, Взрывная душа против групп врагов, Разрубатель душ во время Огненного погребения, затем Разлом, Раскалывание душ, Клинок Скверны, Опустошение Скверной. Разрушитель: потратить готовый Безднопад Взрывной душой или Раскалыванием душ, Разлом при двух наложениях Безднопада, Метаморфоза, Взрывная душа, Печать злобы, Разлом при полных зарядах, Обжигающий жар, Печать огня, Разлом, Раскалывание душ, Клинок Скверны, Бросок боевого клинка. Напоминания: Демонические шипы, Прерывание, Затуманивание."
